    """Decompress possibly concatenated zstd frames. Returns (decompressed_bytes, frames_info list) or raises."""
    lib = get_zstd()
    if lib is None:
        raise RuntimeError("libzstd not found")
    out_parts = []
    frames = []
    pos = 0
    total = len(data)
    if total == 0:
