    # Setup DCtx for dict case
    dctx = None
    if dict_data is not None:
        dctx = lib.ZSTD_createDCtx()
        if not dctx:
            raise RuntimeError("create DCtx failed")
        ret = lib.ZSTD_DCtx_loadDictionary(dctx, dict_data, len(dict_data))
        if lib.ZSTD_isError(ret):
            lib.ZSTD_freeDCtx(dctx)
            raise RuntimeError(lib.ZSTD_getErrorName(ret).decode() if lib.ZSTD_getErrorName(ret) else "dict load error")
    try:
        while pos < total:
            remaining = total - pos
            if remaining < 4:
                raise RuntimeError("trailing")
            chunk = data[pos:]
            csize = lib.ZSTD_findFrameCompressedSize(chunk, remaining)
            if lib.ZSTD_isError(csize):
                raise RuntimeError(lib.ZSTD_getErrorName(csize).decode() if lib.ZSTD_getErrorName(csize) else "error")
            if csize == 0 or csize > remaining:
                raise RuntimeError("bad frame size")
            csize_content = lib.ZSTD_getFrameContentSize(chunk, remaining)
            if csize_content == ZSTD_CONTENTSIZE_ERROR:
