            if csize_content != ZSTD_CONTENTSIZE_UNKNOWN:
                out_size = int(csize_content)
                if out_size == 0:
                    out_buf = ctypes.create_string_buffer(1)
                    if dctx is not None:
                        ret = lib.ZSTD_decompressDCtx(dctx, out_buf, 0, chunk, csize)
                    else:
                        ret = lib.ZSTD_decompress(out_buf, 0, chunk, csize)
                    if lib.ZSTD_isError(ret):
                        raise RuntimeError(lib.ZSTD_getErrorName(ret).decode())
                    out_parts.append(b"")
                    frames.append((csize, 0))
                else:
                    out_buf = ctypes.create_string_buffer(out_size)
                    if dctx is not None:
                        ret = lib.ZSTD_decompressDCtx(dctx, out_buf, out_size, chunk, csize)
                    else:
                        ret = lib.ZSTD_decompress(out_buf, out_size, chunk, csize)
                    if lib.ZSTD_isError(ret):
                        raise RuntimeError(lib.ZSTD_getErrorName(ret).decode())
                    out_parts.append(out_buf.raw[:ret])
                    frames.append((csize, ret))
            else:
                buf_size = 1024*1024
                success = False
                last_err = ""
                for _ in range(8):
                    out_buf = ctypes.create_string_buffer(buf_size)
                    if dctx is not None:
                        ret = lib.ZSTD_decompressDCtx(dctx, out_buf, buf_size, chunk, csize)
                    else:
                        ret = lib.ZSTD_decompress(out_buf, buf_size, chunk, csize)
                    if not lib.ZSTD_isError(ret):
